css:
.print-format { page-size: A5; orientation: Portrait; max-width: 148mm; font-size: 10pt; }
@media print { .print-format { margin: 0; padding: 0; } }
@page { size: A5 portrait; margin: 8mm 10mm; }
.slip-title p { margin: 0; font-weight: bold; font-size: 11pt; }
.slip-heading { margin: 8px 0; }
.slip-heading p { margin: 0 0 6px; }
.slip-row { margin: 6px 0; }
.slip-value { display: inline-block; min-width: 28mm; border-bottom: 1px dotted #333; padding: 0 4px; font-weight: bold; }
.slip-station { margin: 10px 0; }
.slip-station p { margin: 0; }
.slip-authorised { width: 100%; margin-top: 12px; border-collapse: collapse; }
.slip-authorised td { vertical-align: bottom; padding: 0; }
.slip-person { display: block; min-width: 60mm; margin-bottom: 2px; }
.slip-stamp { width: 40mm; height: 20mm; border: 1px solid #333; text-align: center; vertical-align: middle !important; font-size: 8pt; color: #555; }
.slip-footer { border-top: 1px solid #333; margin-top: 10px; padding-top: 4px; font-size: 7.5pt; }
.slip-footer p { margin: 0 0 3px; }
.instruction { border: 1px solid #333; padding: 3px; }
.expiry-warning { border: 1px solid #a00; padding: 3px; font-weight: bold; }
.signature-table { width: 100%; border-collapse: separate; border-spacing: 8px 4px; margin: 0 -8px; }
.signature-table td { width: 50%; vertical-align: top; }
.signature-line { border-bottom: 1px solid #333; height: 14px; margin-bottom: 2px; }
.print-format .slip-authorised td, .print-format .signature-table td { padding: 0 !important; }
